/bin/bash -lc "python3 - <<'PY'
import ast,json,hashlib,difflib
from pathlib import Path
p=json.loads(Path('proposal.json').read_text());r=json.load(open('runtime_view.json'));schema=r['study_schema']
def check(value,schema,path='"'$'"'):
 typ=schema.get('type'); types={'object':dict,'array':list,'string':str}
 if typ:assert isinstance(value,types[typ]),(path,typ)
 if 'const' in schema:assert value==schema['const'],path
 if 'enum' in schema:assert value in schema['enum'],path
 if isinstance(value,str) and 'minLength' in schema:assert len(value)>=schema['minLength'],path
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=set(value),(path,'missing')
  if schema.get('additionalProperties') is False:assert set(value)<=set(schema['properties']),(path,'extra')
  for k,v in value.items():
   if k in schema.get('properties',{}):check(v,schema['properties'][k],path+'.'+k)
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  if 'items' in schema:
   for i,v in enumerate(value):check(v,schema['items'],path+f'[{i}]')
check(p['study'],schema)
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
allowed=set(r['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert 1<=len(p['variants'])<=4
assert len(set(v['name'] for v in p['variants']))==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
for v in p['variants']:
 path=Path(v['file']);assert path.name==v['file'] and path.suffix=='.py'
 source=path.read_text();tree=ast.parse(source);compile(source,str(path),'exec')
 cfg=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert cfg==v['config'],path
 for n in ast.walk(tree):
  if isinstance(n,ast.Import):assert all(a.name.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'} for a in n.names)
  elif isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
  elif isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','eval','exec','__import__','compile'},(path,n.func.id)
 print('PASS schema/config/syntax/standalone boundary:',v['name'])
for stem in ['full','counts']:
 assert Path(f'membership_{stem}_native_bridge.py').read_bytes()==Path(f'history_g1_r0081_membership_{stem}_native_bridge.py').read_bytes()
 print('PASS exact native-control source hash:',stem)
a=ast.parse(Path('candidate.py').read_text());b=ast.parse(Path('membership_counts_row_local.py').read_text())
for t in [a,b]:
 t.body=[n for n in t.body if not (isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))]
assert ast.dump(a)==ast.dump(b)
orig=ast.parse(Path('history_g1_r0081_membership_counts_native_bridge.py').read_text())
om=next(x for x in orig.body if isinstance(x,ast.ClassDef) and x.name=='Model');nm=next(x for x in a.body if isinstance(x,ast.ClassDef) and x.name=='Model')
changed=[]
for o,n in zip([n for n in om.body if isinstance(n,ast.FunctionDef)],[n for n in nm.body if isinstance(n,ast.FunctionDef) and n.name"'!='"'_row_local_dice']):
 assert o.name==n.name
 if ast.dump(o)"'!=ast.dump(n):changed.append(o.name)
assert changed==['"'__init__','_folded_support_activation','_primary_activation'],changed
of={n.name:ast.dump(n) for n in orig.body if isinstance(n,ast.FunctionDef)}
nf={n.name:ast.dump(n) for n in a.body if isinstance(n,ast.FunctionDef)}
assert of==nf
print('PASS local pair differs only in CONFIG; inherited compression, forward, loss and VJP ASTs unchanged.')
print('Changed methods:',changed,'plus new _row_local_dice helper')
print('--- new-source diff, excluding long CONFIG line ---')
s=Path('history_g1_r0081_membership_counts_native_bridge.py').read_text().splitlines(True);t=Path('candidate.py').read_text().splitlines(True)
for l in difflib.unified_diff(s,t):
 if not l.startswith(('-CONFIG','+CONFIG')):print(l,end='')
PY"

